insert into public.page_sections (id, enabled, key, settings, content_en, content_ar, page_slug, sort_order, created_at, updated_at) values ('e1d70a27-db9c-4595-a010-25b28fb6a714', true, 'hero', '{"chromeImage":"assets/identity/chrome.webp","heroVideo":"","stickerImage":"assets/identity/creativity.webp","buttonHref":"#services","scrollHref":"#work"}'::jsonb, '{"topline":"MEET 5CHICKS / YOUR CREATIVE HOUSE","toplineEnd":"CREATIVE HOUSE","titleLine1":"SMALL CHICKS.","titleLine2":"BIG ","titleHighlight":"ENERGY","description":"5CHICKS is a creative house bringing design, technology and storytelling together. We build brands, create content and produce experiences with one connected team.","buttonLabel":"Discover our services","coordinateTop":"IDEAS INTO IMPACT","coordinateBottom":"FIVE FORCES IN MOTION","sticker":"A LITTLE DIFFERENT.\nA LOT OF CHARACTER.","labelStrong":"PURE","labelText":"CREATIVE DNA","bottomText":"STRATEGY MEETS INSTINCT.","scrollLabel":"SCROLL TO DISCOVER"}'::jsonb, '{"topline":"اتعرّف على 5CHICKS / بيتك الإبداعي","toplineEnd":"بيت إبداعي متكامل","titleLine1":"حجمنا صغير.","titleLine2":"","titleHighlight":"إبداعنا كبير","description":"5CHICKS بيت إبداعي بيجمع التصميم والتكنولوجيا وصناعة القصص. بنبني علامات تجارية، ونصنع محتوى وتجارب متكاملة بفريق واحد.","buttonLabel":"اكتشف خدماتنا","coordinateTop":"من الفكرة للتأثير","coordinateBottom":"خمس قوى إبداعية في حركة","sticker":"اختلاف في التفكير.\nشخصية في كل تفصيلة.","labelStrong":"إبداع","labelText":"في كل تفصيلة","bottomText":"استراتيجية بروح إبداعية.","scrollLabel":"اكتشف أكتر"}'::jsonb, 'home', 1, '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.page_sections (id, enabled, key, settings, content_en, content_ar, page_slug, sort_order, created_at, updated_at) values ('1d4e4d58-8195-435f-a1a4-a0f403ee070e', true, 'ticker', '{"items":[{"enabled":true},{"enabled":true},{"enabled":true}]}'::jsonb, '{"items":[{"text":"GOOD IDEAS HATCH HERE"},{"text":"BUILT TO STAND OUT"},{"text":"FIVE MINDS. NO LIMITS."}]}'::jsonb, '{"items":[{"text":"هنا بتبدأ الأفكار"},{"text":"اتخلقنا علشان نتميّز"},{"text":"خمس عقول. بلا حدود."}]}'::jsonb, 'home', 2, '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.page_sections (id, enabled, key, settings, content_en, content_ar, page_slug, sort_order, created_at, updated_at) values ('d2a2a850-d859-496f-a352-4c0a4f1e4e1b', true, 'about', '{"symbolImage":"assets/identity/symbol.webp","linkHref":"#services"}'::jsonb, '{"eyebrow":"WHO WE ARE","title":"FIVE FORCES.","titleHighlight":"ONE\nHOUSE.","lead":"Five creative forces. One connected team.","paragraphs":[{"text":"We are designers, developers, storytellers and makers. Our name brings five creative forces under one roof: design, programming, media production, branding and directing."},{"text":"We connect creative thinking with a clear purpose. From shaping a brand to producing its next campaign, we work across disciplines to turn an idea into a complete experience."}],"linkLabel":"Find your next creative service","missionLabel":"OUR MISSION","mission":"To bring strategy, creativity and digital experience together in work that supports our partners’ goals.","visionLabel":"OUR VISION","vision":"To help businesses adapt, grow and stand out through purposeful creative and technological solutions."}'::jsonb, '{"eyebrow":"إحنا مين","title":"خمس قوى.","titleHighlight":"بيت\nواحد.","lead":"خمس قوى إبداعية. فريق واحد متكامل.","paragraphs":[{"text":"إحنا مصممين ومطوّرين وصنّاع محتوى وحكايات. اسمنا بيجمع خمس قوى إبداعية تحت سقف واحد: التصميم، والبرمجة، والإنتاج الإعلامي، والبراندينج، والإخراج."},{"text":"بنربط التفكير الإبداعي بهدف واضح. من بناء هوية البراند لإنتاج حملته الجاية، بنجمع تخصصاتنا علشان نحوّل الفكرة لتجربة متكاملة."}],"linkLabel":"اكتشف الخدمة المناسبة لمشروعك","missionLabel":"رسالتنا","mission":"نجمع الاستراتيجية والإبداع والخبرة الرقمية في شغل يخدم أهداف شركائنا ويعبّر عنهم.","visionLabel":"رؤيتنا","vision":"نساعد الشركات تتطور وتكبر وتتميّز، بحلول إبداعية وتكنولوجية ليها هدف وتأثير."}'::jsonb, 'home', 3, '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
