insert into public.services (id, slug, sort_order, published, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, overview_en, overview_ar, color, icon_url, hero_image_url, work_link, whatsapp_message_en, whatsapp_message_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, og_image_url, created_at, updated_at) values ('75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'digital-marketing', 0, true, 'Digital Marketing', 'التسويق الرقمي', 'A clear message. In the right places.', 'رسالة واضحة. في المكان الصح.', 'We connect your brand with its audience through a considered content direction and a consistent social presence. From planning a campaign to shaping the posts around it, every piece has a role in the bigger story.', 'بنوصل البراند بجمهوره من خلال اتجاه واضح للمحتوى وحضور متناسق على السوشيال ميديا. من تخطيط الحملة لكتابة وتصميم كل بوست، كل تفصيلة ليها دور في الحكاية الأكبر.', 'Digital marketing at 5CHICKS is about giving your brand a clear voice online. We shape the direction of your content, plan how it appears across social media, and create the copy and visuals that carry each campaign.
insert into public.services (id, slug, sort_order, published, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, overview_en, overview_ar, color, icon_url, hero_image_url, work_link, whatsapp_message_en, whatsapp_message_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, og_image_url, created_at, updated_at) values ('3b600249-5429-44ed-a631-238925dd35e7', 'branding', 1, true, 'Branding', 'الهوية التجارية', 'Build a brand people recognise.', 'براند يتعرف من أول نظرة.', 'We give your brand a visual language that reflects who you are. Logo, colour, typography and applications come together as a coherent identity that can grow with your business.', 'بنبني لغة بصرية تعبّر عن شخصية البراند. اللوجو والألوان والخطوط وتطبيقاتها بيكملوا بعض في هوية واحدة متناسقة، تقدر تكبر مع مشروعك.', 'Branding is where a business gets its visual language. We design the logo, choose the colours and typography, and show how they work across real applications, so your identity feels consistent wherever people meet it.
insert into public.services (id, slug, sort_order, published, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, overview_en, overview_ar, color, icon_url, hero_image_url, work_link, whatsapp_message_en, whatsapp_message_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, og_image_url, created_at, updated_at) values ('9b593ad5-300f-48b2-a253-1ff5b1887f58', 'software', 2, true, 'Software', 'البرمجيات', 'Good ideas deserve a useful experience.', 'الفكرة الحلوة تستاهل تجربة سهلة.', 'We bring design and programming together to shape digital experiences around real business needs. From the way a website looks to the way it works, clarity and usability guide the process.', 'بنجمع التصميم والبرمجة علشان نعمل تجارب رقمية مبنية على احتياجات حقيقية. من شكل الموقع لطريقة استخدامه، الوضوح وسهولة التجربة هما أساس كل خطوة.', 'Software at 5CHICKS brings design and programming together in one team. We design and build websites and digital experiences around what your business actually needs, with clarity and usability guiding every decision.
insert into public.services (id, slug, sort_order, published, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, overview_en, overview_ar, color, icon_url, hero_image_url, work_link, whatsapp_message_en, whatsapp_message_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, og_image_url, created_at, updated_at) values ('6007059d-9c46-4d58-ae47-6fc89269a87d', 'media-production', 3, true, 'Media Production', 'الإنتاج الإعلامي', 'From the first idea to the final frame.', 'من أول فكرة لآخر كادر.', 'We turn concepts into visual stories through direction, photography and video production. Whether it is a reel, a film or a sketch, the idea leads the way from planning and shooting to the final edit.', 'بنحوّل الأفكار لحكايات بصرية من خلال الإخراج والتصوير وإنتاج الفيديو. سواء ريل أو فيلم أو سكتش، الفكرة بتقود كل مرحلة: من التحضير والتصوير لحد المونتاج النهائي.', 'Media production turns a concept into a visual story. We handle direction, photography and video production, and the idea leads the way from planning and shooting to the final edit.
insert into public.services (id, slug, sort_order, published, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, overview_en, overview_ar, color, icon_url, hero_image_url, work_link, whatsapp_message_en, whatsapp_message_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, og_image_url, created_at, updated_at) values ('e72e2250-1007-4135-a7f8-4ecc84beba69', 'visual-art', 4, true, 'Visual Art', 'الفنون البصرية', 'Give your idea a visual point of view.', 'خلّي لفكرتك شكل يعبّر عنها.', 'We create visuals that express a brand’s personality and make its message tangible. Composition, colour and image-making come together across campaign artwork, digital content and promotional materials.', 'بنصنع صور وتصميمات تعكس شخصية البراند وتوصل رسالته. التكوين والألوان ومعالجة الصور بيجتمعوا في تصميمات الحملات والمحتوى الرقمي والمواد الدعائية.', 'Visual art gives your idea a visual point of view. We create visuals that express your brand’s personality and make its message tangible.
insert into public.service_items (id, service_id, kind, sort_order, title_en, title_ar, body_en, body_ar, created_at, updated_at) values ('14420816-f412-4c13-a500-b8a1639c7adb', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'deliverable', 0, 'Content strategy & campaign concepts', 'استراتيجية المحتوى وأفكار الحملات', 'A considered direction for what your brand says, turned into campaign ideas where every piece has a clear role.', 'اتجاه واضح للي البراند بيقوله، بيتحول لأفكار حملات كل تفصيلة فيها ليها دور.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
