insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('e1285903-01e8-4c9f-a020-6ed66765f054', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'value', 0, 'A clear message', 'Content with a direction says one thing well, instead of many things at once.', 'رسالة واضحة', 'المحتوى اللي له اتجاه بيقول حاجة واحدة كويس، بدل حاجات كتير مرة واحدة.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
