insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('b9e776d9-ebf6-4f8d-a39e-801c73f3b6a4', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'value', 2, 'One connected team', 'Strategy, design and production work together, so the idea survives all the way to the final post.', 'فريق واحد متكامل', 'الاستراتيجية والتصميم والإنتاج بيشتغلوا مع بعض، فالفكرة بتفضل واضحة لحد آخر بوست.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('664f45e5-8340-4495-a264-2cccef7e22e6', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'faq', 0, 'What does the digital marketing service include?', 'Content strategy and campaign concepts, social media content planning, and creative copy and campaign visuals.', 'خدمة التسويق الرقمي بتشمل إيه؟', 'استراتيجية المحتوى وأفكار الحملات، وتخطيط محتوى السوشيال ميديا، وكتابة المحتوى وتصميمات الحملات.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('42abdbc2-7433-4d0c-ab90-f9a9a5e600b2', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'faq', 1, 'Can you also produce the content?', 'Yes. Media production, visual art and branding are also 5CHICKS services, so campaign content can be designed, shot and edited by the same team.', 'ممكن تنتجوا المحتوى كمان؟', 'أيوه. الإنتاج الإعلامي والفنون البصرية والبراندينج من خدمات 5CHICKS برضه، فمحتوى الحملة ممكن يتصمم ويتصور ويتعمله مونتاج بنفس الفريق.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('2117b1df-2925-4587-ad8e-9916edefcff6', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'faq', 2, 'Can I see examples of your work?', 'Our company portfolio includes a digital marketing section, and the reels collection on our homepage shows short-form content we have produced.', 'أقدر أشوف أمثلة من شغلكم؟', 'بورتفوليو الشركة فيه جزء للتسويق الرقمي، ومجموعة الريلز في الصفحة الرئيسية بتعرض محتوى قصير من إنتاجنا.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('0d7207b4-8214-4e3e-a53b-67f32666f522', '75c0bf58-7592-4e6d-ab1c-b981ca35b11e', 'faq', 3, 'How much does it cost?', 'Pricing is not published on the website. Send us your project details on WhatsApp and we will talk it through with you.', 'التكلفة كام؟', 'الأسعار مش منشورة على الموقع. ابعتلنا تفاصيل مشروعك على واتساب ونتكلم فيها سوا.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
