insert into public.service_items (id, service_id, kind, sort_order, title_en, body_en, title_ar, body_ar, created_at, updated_at) values ('784a3201-ca17-4ba0-aef1-8f8fc6335c27', '6007059d-9c46-4d58-ae47-6fc89269a87d', 'faq', 2, 'Do you only edit, or also shoot?', 'Both. The service covers the whole journey, from planning and shooting to the final edit.', 'بتعملوا مونتاج بس ولا تصوير كمان؟', 'الاتنين. الخدمة بتغطي الرحلة كلها، من التحضير والتصوير لحد المونتاج النهائي.', '2026-09-26T00:00:00.000Z', '2026-09-26T00:00:00.000Z') on conflict (id) do nothing;
